parameters.jsCode:
// Trim a raw CI log down to the signal.
//
// A failed build can emit thousands of lines. Sending the whole thing to the
// model is slow, expensive, and buries the cause. So we:
//   1. strip ANSI colour codes and drop pure progress noise (bars, percentages)
//   2. always keep every line matching an error keyword - the actual failures
//   3. keep a slice of the head (environment / setup context)
//   4. keep a slice of the tail (where test runners print their summary)
//   5. de-duplicate and cap the total size so we never blow the context window
// Error lines are never dropped by the noise filter, so nothing that matters is lost.

const http = $input.first().json;
const body = $('Webhook - CI Failure Callback').first().json.body || {};

const ERROR_PATTERN = /(error|failed|failure|exception|traceback|assert|panic|fatal|timeout|timed out|refused|denied|unauthori[sz]ed|cannot|could not|not found|no such file|out of memory|npm err|segmentation fault)/i;

// Pure progress noise: percentages, progress bars, chunk download counters.
const NOISE_PATTERN = /(\d{1,3}%|\[=+>?\s*\]|Downloading|Uploading|Progress \()/;

const stripAnsi = (text) => text.replace(/\u001b\[[0-9;]*m/g, '');

const raw = typeof http.data === 'string' ? http.data : JSON.stringify(http.data || '');
const rawLines = stripAnsi(raw).split(/\r?\n/);

const totalLines = rawLines.length;
const errorLines = rawLines.filter((line) => ERROR_PATTERN.test(line));

// Drop noise unless the line is an error (errors always win).
const signalLines = rawLines.filter((line) => ERROR_PATTERN.test(line) || !NOISE_PATTERN.test(line));
const noiseLinesRemoved = totalLines - signalLines.length;

const HEAD_LINES = 30;
const TAIL_LINES = 160;
const head = signalLines.slice(0, HEAD_LINES);
const tail = signalLines.slice(Math.max(HEAD_LINES, signalLines.length - TAIL_LINES));

// De-duplicate while preserving first-seen order to strip repeated stack frames.
const picked = [];
const seen = new Set();
for (const line of [...head, ...errorLines, ...tail]) {
  if (seen.has(line)) continue;
  seen.add(line);
  picked.push(line);
}

const MAX_CHARS = 14000;
let excerpt = picked.join('\n');
const truncated = excerpt.length > MAX_CHARS;
if (truncated) excerpt = excerpt.slice(0, MAX_CHARS);

return [
  {
    json: {
      job_name: body.jobName || 'Not specified',
      build_url: body.buildUrl || '',
      branch: body.branch || 'Not specified',
      commit: body.commit || 'Not specified',
      ci_status: body.status || 'FAILURE',
      log_url: body.logUrl || '',
      total_lines: totalLines,
      error_line_count: errorLines.length,
      noise_lines_removed: noiseLinesRemoved,
      excerpt_lines: picked.length,
      truncated,
      log_excerpt: excerpt || 'Not specified',
      error_lines_excerpt: errorLines.slice(-40).join('\n') || 'Not specified',
    },
  },
];

